const fetch = require('node-fetch');
const { URLSearchParams } = require('url');

// ================= CONFIG =================
const solr = JSON.parse($vars.solr_config);

const SOLR_URL = `${solr.base_url}/policy_vectors/select`;
const EMBEDDING_API = $vars.endpoint+':5000/embed';

const VECTOR_FIELD = 'embedding';
const TEXT_FIELD = 'text';

const TOP_K = 5;
const FETCH_K = 20;
const RRF_K = 60;

// ================= AUTH HEADER =================
const authHeader = 'Basic ' + Buffer.from(`${solr.user}:${solr.pass}`).toString('base64');;

// ================= EMBEDDING =================
async function getEmbedding(text) {
    const response = await fetch(EMBEDDING_API, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text })
    });

    if (!response.ok) throw new Error(`Embedding API Error: ${await response.text()}`);

    const data = await response.json();
    return Array.isArray(data[0]) ? data[0] : data;
}

// ================= KEYWORD SEARCH =================
async function keywordSearch(query) {
    const sanitized = query.replace(/[+\-&|!(){}[\]^"~*?:\\/]/g, ' ').trim();

    const params = new URLSearchParams();
    params.append('q', `${TEXT_FIELD}:(${sanitized})`);
    params.append('fl', `id,${TEXT_FIELD},score`);
    params.append('rows', String(FETCH_K));
    params.append('wt', 'json');

    const response = await fetch(SOLR_URL, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Authorization': authHeader
        },
        body: params.toString()
    });

    if (!response.ok) throw new Error(`Keyword search failed: ${response.status} ${await response.text()}`);

    const data = await response.json();
    return data.response?.docs || [];
}

// ================= VECTOR SEARCH =================
async function vectorSearch(embedding) {
    const vectorStr = `[${embedding.join(",")}]`;

    const params = new URLSearchParams();
    params.append('q', `{!knn f=${VECTOR_FIELD} topK=${FETCH_K}}${vectorStr}`);
    params.append('fl', `id,${TEXT_FIELD},score`);
    params.append('rows', String(FETCH_K));
    params.append('wt', 'json');

    const response = await fetch(SOLR_URL, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Authorization': authHeader
        },
        body: params.toString()
    });

    if (!response.ok) throw new Error(`Vector search failed: ${response.status} ${await response.text()}`);

    const data = await response.json();
    return data.response?.docs || [];
}

// ================= RRF =================
function reciprocalRankFusion(keywordDocs, vectorDocs, k = RRF_K) {
    const scores = {};
    const docMap = {};

    keywordDocs.forEach((doc, rank) => {
        const id = doc.id;
        scores[id] = (scores[id] || 0) + 1 / (k + rank + 1);
        docMap[id] = doc;
    });

    vectorDocs.forEach((doc, rank) => {
        const id = doc.id;
        scores[id] = (scores[id] || 0) + 1 / (k + rank + 1);
        docMap[id] = doc;
    });

    return Object.entries(scores)
        .sort(([, a], [, b]) => b - a)
        .slice(0, TOP_K)
        .map(([id]) => docMap[id]);
}

// ================= MAIN =================
try {
    const embedding = await getEmbedding($searchQuery);

    const [keywordDocs, vectorDocs] = await Promise.all([
        keywordSearch($searchQuery),
        vectorSearch(embedding)
    ]);

    if (keywordDocs.length === 0 && vectorDocs.length === 0) {
        return `DEBUG: Both searches returned 0 results for query: "${$searchQuery}"`;
    }

    const finalDocs = reciprocalRankFusion(keywordDocs, vectorDocs);

    const context = finalDocs.map((doc, index) => {
        const content = Array.isArray(doc[TEXT_FIELD])
            ? doc[TEXT_FIELD].join(' ')
            : (doc[TEXT_FIELD] || "N/A");

        return `[Context ${index + 1}]: ${content}`;
    }).join('\n\n');

    return context;

} catch (error) {
    return `Search Error: ${error.message}`;
}
